using FBS.Student.Native;
int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
var g=new PowerCommandGate();var id=Guid.NewGuid().ToString();
Check(!g.Begin(id,"shutdown",30000,false,0),"untrusted endpoint denied");Check(!g.Begin("wrong","shutdown",30000,true,0),"invalid identifier denied");Check(!g.Begin(id,"shell",30000,true,0),"arbitrary command denied");Check(!g.Begin(id,"sleep",2999,true,0),"almost expired command denied");Check(!g.Begin(id,"restart",30001,true,0),"excessive lifetime denied");Check(g.Begin(id,"sleep",30000,true,0),"bounded request can be prepared");Check(g.Claim(id,1),"request claimed once after controller acknowledgement");Check(!g.Claim(id,2),"duplicate execution denied");Check(!g.Begin(id,"sleep",30000,true,2),"request replay denied");var next=Guid.NewGuid().ToString();Check(g.Begin(next,"restart",5000,true,10),"fresh next request prepared");Check(!g.Claim(next,5010),"expiry denied");var final=Guid.NewGuid().ToString();Check(g.Begin(final,"shutdown",5000,true,6000),"whitelisted shutdown prepared");g.Cancel();Check(!g.Claim(final,6001),"shutdown controller cancel disarms request");
Console.WriteLine($"Power gate: {passed} passed. No system power request executed.");
